/**
 * Shell auto-completion script generators for `dhatugen` (bash, zsh, fish).
 *
 * All three shells delegate candidate generation to the hidden
 * `dhatugen __complete` command, which keeps suggestions in sync with the
 * command registry and the data-derived value sets.
 *
 * `DHATUGEN_BIN` invokes an alternate entrypoint (e.g. `node
 * /path/to/dhatugen/dist/cli.js` or `npx dhatugen`) when the package is not
 * globally linked.
 */

const BIN = '${DHATUGEN_BIN:-dhatugen}';

export function bashCompletionScript(): string {
  return `# dhatugen bash completion v1.0.0
# Generated by: dhatugen completion bash
# Install:      dhatugen completion bash >> ~/.bashrc   (or source it from a dedicated file)
# Requires:     bash >= 4
# Override:     export DHATUGEN_BIN="node /path/to/dhatugen/dist/cli.js"  (optional)
#
# Suggestions are produced by the CLI itself ("dhatugen __complete"), covering
# subcommands, per-command options, enumerated values (scripts, formats,
# lakaras, pratyayas, upasargas, genders, ...) and dhatu identifiers.

_dhatugen_completions() {
  local cur engine_reply
  COMPREPLY=()
  cur="\${COMP_WORDS[COMP_CWORD]}"
  engine_reply="$(${BIN} __complete "\${COMP_WORDS[@]:1:$((COMP_CWORD-1))}" "\${cur}" 2>/dev/null)"
  if [[ $? -eq 0 ]]; then
    COMPREPLY=($(compgen -W "\${engine_reply}" -- "\${cur}"))
  fi
}
complete -F _dhatugen_completions -o nosort dhatugen
`;
}

export function zshCompletionScript(): string {
  return `#compdef dhatugen
# dhatugen zsh completion v1.0.0
# Generated by: dhatugen completion zsh
# Install:     copy this file to a directory in \$fpath, e.g.:
#              mkdir -p ~/.zfunc && dhatugen completion zsh > ~/.zfunc/_dhatugen
#              then add "fpath=(~/.zfunc \$fpath)" before "compinit" in ~/.zshrc.
# Override:    export DHATUGEN_BIN="node /path/to/dhatugen/dist/cli.js"  (optional)

_dhatugen() {
  local -a committed replies
  local n=$((CURRENT-1))
  committed=("\${(@)words[1,n]}")
  replies=(\${(f)"$(${BIN} __complete \${committed} "\${word}" 2>/dev/null)"})
  if [ \${#replies} -gt 0 ]; then
    compadd -Q -- "\${replies[@]}"
  fi
}
compdef _dhatugen dhatugen
`;
}

export function fishCompletionScript(): string {
  return `# dhatugen fish completion v1.0.0
# Generated by: dhatugen completion fish
# Install:     dhatugen completion fish > ~/.config/fish/completions/dhatugen.fish
# Override:    set -x DHATUGEN_BIN "node /path/to/dhatugen/dist/cli.js"  (optional)

function __dhatugen_bin
    if set -q DHATUGEN_BIN[1]
        eval $DHATUGEN_BIN
    else
        dhatugen
    end
end

function __dhatugen_complete
    set -l committed (commandline -opc)
    set -l current (commandline -ct)
    __dhatugen_bin __complete $committed "$current" 2>/dev/null
end
complete -f -c dhatugen -a '(__dhatugen_complete)'
`;
}

export const COMPLETION_SCRIPTS: Record<string, () => string> = {
  bash: bashCompletionScript,
  zsh: zshCompletionScript,
  fish: fishCompletionScript,
};
